def overlay():
    t = [(64, 512, 512)] * 256
    for lv in range(4):
        for gm in range(32):
            y = 64 + ((GND[lv][0] - 64) * gm >> 4)
            t[lv * 32 + gm] = (min(y, 900), GND[lv][1], GND[lv][2])
    for i, c in enumerate(COFFEE): t[128 + i] = c
    for s in range(16): t[144 + s] = (64 + ((WALL[0] - 64) * s >> 4), WALL[1], WALL[2])
    for k, c in CONST.items(): t[160 + k] = c
    return t

def hx(v, n):
    return 'x"%0*X"' % (n, v)

def rows(vals, n, per=12):
    out = []
    for i in range(0, len(vals), per):
        out.append('        ' + ', '.join(hx(v, n) for v in vals[i:i + per]))
    return ',\n'.join(out)

def main():
    L = []
    L.append('-- radiant_pkg.vhd -- GENERATED by radiant.py; edit the generator, not this file.')
    L.append('library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n')
    L.append('package radiant_pkg is')
    L.append('    type t_tab is array(0 to 1023) of std_logic_vector(15 downto 0);')
    L.append('    constant C_TAB : t_tab := (\n' + rows(TAB, 4) + '\n    );')
    L.append('    type t_pal is array(0 to 255) of std_logic_vector(15 downto 0);')
    L.append('    constant C_PALY : t_pal := (\n' + rows([(DUCI[i] << 10) | PAL[i][0] for i in range(256)], 4) + '\n    );')
    L.append('    constant C_PALC : t_pal := (\n' + rows([((p[1] >> 2) << 8) | (p[2] >> 2) for p in PAL], 4) + '\n    );')
    lw = []
    for a, b, c, d in LENS: lw += [(a << 8) | b, (c << 8) | d]
    lw += [0] * (256 - len(lw))                       # a full block RAM (a 64-word ROM maps to logic)
    L.append('    type t_lens is array(0 to 255) of std_logic_vector(15 downto 0);')
    L.append('    constant C_LENS : t_lens := (\n' + rows(lw, 4) + '\n    );')
    ov = overlay()
    L.append('    constant C_OVH : t_pal := (\n' + rows([(y << 6) | (u >> 4) for y, u, v in ov], 4) + '\n    );')
    L.append('    constant C_OVL : t_pal := (\n' + rows([((u & 15) << 12) | (v << 2) for y, u, v in ov], 4) + '\n    );')
    L.append('end package radiant_pkg;')
    open(os.path.join(HERE, 'radiant_pkg.vhd'), 'w').write('\n'.join(L) + '\n')

if __name__ == '__main__':
    main()
